(() => {
  const T = window.__CITY_APP.trafficSystem, s = T.pedRoutes.stats;
  const keys = ['lines', 'walkSides', 'oneSided', 'unwalkedSides', 'bandSides', 'straight', 'followed', 'detoured', 'walkDetours', 'lineBlocked', 'gapBlocked', 'throughFurniture',
    'walkLinks', 'bandLinks', 'built', 'blocked', 'offIsland', 'midBuilt', 'midNoLanding', 'obstacles'];
  const out = Object.fromEntries(keys.map((k) => [k, s[k]]));
  for (const k of ['walkMs', 'followMs', 'detourMs']) out[k] = +(s[k] || 0).toFixed(1);
  console.log('[ride-check] ped-sidewalks start ' + JSON.stringify({ q: location.search, ...out, peds: T.peds.filter((p) => p.placed).length }));
})()

(async () => {
  const C = window.CITY, T = window.__CITY_APP.trafficSystem;
  const walks = C.sidewalkWalkIndex(C.sidewalkPieceMap);
  if (!C.__built) {
    C.__built = new Map();
    for (const bl of C.GEO.buildings) {
      const b = C.blockAt(bl[0], bl[1]);
      if (!b) continue;
      let area = 0;
      for (const [u0, u1, v0, v1] of bl[3]) area += (u1 - u0) * (v1 - v0);
      const s = C.__built.get(b) || { n: 0, area: 0, top: 0 };
      s.n++; s.area += area; s.top = Math.max(s.top, bl[4]);
      C.__built.set(b, s);
    }
  }
  const paved = (b) => (b.cx > -1150 && b.cx < 1500 && b.cz > -2750 && b.cz < 650) || (() => { const s = C.__built.get(b); return !!s && (s.top >= 20 || (s.top >= 14 && s.area / s.n >= 1500)); })();
  const grass = (b) => b.park > 0.6 || (!paved(b) && !(b.wild > 0.5));
  const count = { walk: 0, grass: 0, paved: 0, unmapped: 0, crossing: 0, road: 0 }, lines = { walk: 0, unwalked: 0, band: 0 }, off = [];
  for (let k = 0; k < 16; k++) {
    for (const p of T.peds) {
      if (!p.placed || Math.hypot(p.x - 1640, p.z - -1922) > 90) continue;
      if (p.node || p.mid) { count.crossing++; continue; }
      if (p.route && p.route.edge) lines[['band', 'walk', 'unwalked'][p.route.walk || 0]]++;
      const b = C.blockAt(p.x, p.z);
      const on = b && walks ? walks.inside(b.id, p.x, p.z) : null;
      const key = !b ? 'road' : on === null ? 'unmapped' : on ? 'walk' : grass(b) ? 'grass' : 'paved';
      count[key]++;
      if ((key === 'grass' || key === 'paved') && off.length < 12) off.push([+p.x.toFixed(1), +p.z.toFixed(1), key, p.route ? p.route.walk || 0 : null]);
    }
    await new Promise((res) => setTimeout(res, 500));
  }
  console.log('[ride-check] census winchester ' + JSON.stringify({ q: location.search, samples: 16, radius: 90, count, lines, off }));
})()

